-- SnipRing official sounds. Generated by tools/build_discover.py; safe to re-run (updates existing rows, keeps counters).
on conflict (slug) do update set title_he=excluded.title_he,title_en=excluded.title_en,description_he=excluded.description_he,description_en=excluded.description_en,type=excluded.type,duration_ms=excluded.duration_ms,moods=excluded.moods,tags=excluded.tags,audio_path=excluded.audio_path,peaks=excluded.peaks,visibility=excluded.visibility,status=excluded.status;
select count(*) as official_sounds from public.sounds where origin='official';
